"""Observed reply values and bounded continuation estimates; never an execution policy.

All currency comparisons use the same supplier-economic scenarios on both sides.
Reply probabilities and counter scenarios are estimates, not calibrated facts.
"""

import math
from collections import Counter

from arena_kit.cost import closing_terms, must_haves_ok

OUTCOMES = ('accepted_proposal', 'improved_counteroffer', 'unchanged_offer', 'worse_offer', 'walkout')
COUNTERS = OUTCOMES[1:4]


def paired_gain(th, before, after):
    old, new = th.economics.breakdowns(before), th.economics.breakdowns(after)
    values = [sum(a.values()) - sum(b.values()) for a, b in zip(old, new, strict=True)]
    return {'mean': sum(values) / len(values), 'low': min(values), 'high': max(values)}


def features(th, terms, before, status, repeats):
    old = closing_terms(th.beliefs.case, before, th.std)
    new = closing_terms(th.beliefs.case, terms, th.std)
    pressure = th.beliefs.pressure_summary(new, old)
    levers = {k: new[k] for k in th.beliefs.case['negotiable'] if k != 'unit_price' and new[k] != old[k]}
    return {'pressure': pressure['mean'], 'pressure_range': [pressure['low'], pressure['high']],
            'price_request_fraction': (old['unit_price'] - new['unit_price']) / max(0.01, old['unit_price']),
            'levers': levers, 'status': status, 'repeats': repeats,
            'opening': before == th.reference or all(before.get(k) == v for k, v in th.reference.items()
                                                    if k in before)}


def comparable(th, x):
    rows = []
    for row in getattr(th, 'response_history', []):
        y = row['features']
        if y['status'] == 'final_offer' or x['status'] == 'final_offer':
            if y['status'] != x['status']:
                continue
        # Unmatched multi-package choices cannot identify the supplier's trade-off.
        if not row['identified_offer']:
            continue
        mismatches = sum(x['levers'].get(k) != y['levers'].get(k) for k in set(x['levers']) | set(y['levers']))
        distance = 8 * abs(x['pressure'] - y['pressure']) + mismatches * 1.5
        distance += 0.7 * (x['opening'] != y['opening']) + 0.3 * abs(x['repeats'] - y['repeats'])
        rows.append((math.exp(-distance), row))
    rows.sort(key=lambda pair: pair[0], reverse=True)
    rows = rows[:12]
    counts = Counter(row['session_id'] for _, row in rows)
    return [(weight / counts[row['session_id']], row) for weight, row in rows]


def reply_probabilities(th, terms, before, status, repeats, neighbors=None):
    b = th.beliefs
    base = {k: sum(p.weight * b.probabilities(terms, p, before['unit_price'], repeats,
                                             standing=before)[k] for p in b.particles)
            for k in ('accept', 'counter', 'walk')}
    neighbors = comparable(th, features(th, terms, before, status, repeats)) if neighbors is None else neighbors
    # Equal one-observation pseudo-counts express ignorance about counter quality.
    counts = {k: 1.0 for k in COUNTERS}
    for weight, row in neighbors:
        if row['economic_label'] in counts:
            counts[row['economic_label']] += weight
    total = sum(counts.values())
    return {'accepted_proposal': base['accept'], 'walkout': base['walk'],
            **{k: base['counter'] * v / total for k, v in counts.items()}}


def projected_reply(th, before, terms, row):
    """Transfer a recorded response fraction and actual lever choices, not an old quote."""
    b = closing_terms(th.beliefs.case, before, th.std)
    ask = closing_terms(th.beliefs.case, terms, th.std)
    old, offered, reply = row['before'], row['offered'], row['returned']
    gap = old['unit_price'] - offered['unit_price']
    if abs(gap) < 0.01:
        # No identified numerical response slope to transfer to a different price request.
        if abs(b['unit_price'] - ask['unit_price']) > 0.01:
            return None
        price = b['unit_price'] * reply['unit_price'] / old['unit_price']
    else:
        if (b['unit_price'] - ask['unit_price']) * gap < 0:
            return None
        fraction = (old['unit_price'] - reply['unit_price']) / gap
        if not -1 <= fraction <= 2:
            return None
        price = b['unit_price'] - fraction * (b['unit_price'] - ask['unit_price'])
    candidate = dict(b, unit_price=round(price, 2))
    for key in th.beliefs.case['negotiable']:
        if key == 'unit_price':
            continue
        if reply.get(key) == offered.get(key):
            candidate[key] = ask[key]
        elif reply.get(key) != old.get(key):
            # A third value is evidence, but not a transferable concession rule.
            return None
    return candidate if candidate['unit_price'] > 0 and must_haves_ok(th.beliefs.case, candidate, th.std) else None


def action_value(th, terms, before, status, repeats, secured, valid, current_cost):
    x = features(th, terms, before, status, repeats)
    neighbors = comparable(th, x)
    probabilities = reply_probabilities(th, terms, before, status, repeats, neighbors)
    branch = {'accepted_proposal': paired_gain(th, before, terms),
              'unchanged_offer': {'mean': 0.0, 'low': 0.0, 'high': 0.0},
              'walkout': {'mean': -secured, 'low': -secured, 'high': -secured}}
    scenarios = []
    for weight, row in neighbors:
        if row['economic_label'] not in ('improved_counteroffer', 'worse_offer') or not row['returned']:
            continue
        reply = projected_reply(th, before, terms, row)
        if reply is None or not valid(reply):
            continue
        gain = paired_gain(th, before, reply)
        kind = 'improved_counteroffer' if gain['mean'] > 0.01 else 'worse_offer' if gain['mean'] < -0.01 else 'unchanged_offer'
        if kind == 'unchanged_offer':
            continue
        scenarios.append({'weight': weight, 'kind': kind, 'terms': reply, 'gain': gain,
                          'event_id': row['event_id'], 'session_id': row['session_id']})
    # These are explicit ignorance scenarios when data cannot support a branch.
    # A deterioration can lose all currently secured reward. Do not assume the old quote survives.
    target = max(0.0, branch['accepted_proposal']['mean'])
    for kind in ('improved_counteroffer', 'worse_offer'):
        rows = [s for s in scenarios if s['kind'] == kind]
        if rows:
            total = sum(s['weight'] for s in rows)
            branch[kind] = {'mean': sum(s['weight'] * s['gain']['mean'] for s in rows) / total,
                            'low': min(s['gain']['low'] for s in rows),
                            'high': max(s['gain']['high'] for s in rows), 'source': 'projected comparable replies'}
        else:
            low, high = (0.0, target) if kind == 'improved_counteroffer' else (-secured, 0.0)
            branch[kind] = {'mean': (low + high) / 2, 'low': low, 'high': high,
                            'source': 'unobserved branch: explicit broad scenario, midpoint is an assumption'}
    # A rational terminal choice can decline a deteriorated deal; no deal is zero Arena reward.
    # It cannot recover the withdrawn old offer. The secured-reward floor is therefore -secured.
    for values in branch.values():
        for key in ('mean', 'low', 'high'):
            values[key] = max(-secured, values[key])
    estimate = {k: sum(probabilities[label] * branch[label][k] for label in OUTCOMES)
                for k in ('mean', 'low', 'high')}
    sessions = sorted({row['session_id'] for _, row in neighbors})
    evidence = {'observations': len(neighbors), 'independent_sessions': len(sessions),
                'session_ids': sessions, 'event_ids': [row['event_id'] for _, row in neighbors],
                'similarity_weight': sum(w for w, _ in neighbors),
                'unknown_branches': [k for k, v in branch.items() if v.get('source', '').startswith('unobserved')]}
    return {'pressure': x, 'probabilities': probabilities, 'branches': branch,
            'expected_extra_savings_eur': estimate, 'evidence': evidence,
            'assumptions': 'One supplier reply then close best feasible received deal or decline; old quote not guaranteed. '
                           'Probability estimates and scenario endpoints are not calibrated confidence bounds.',
            '_scenarios': scenarios, '_current_cost': current_cost}


def add_continuation_values(agent, board):
    """Price every candidate, then a bounded optional follow-up for four distinct packages.

    This is advisory lookahead. Astra may choose any validated menu package. No new LLM calls.
    """
    for sid, supplier in board['suppliers'].items():
        th = agent.threads[sid]
        baseline = supplier.get('standing') or supplier['opening_comparison']
        before = baseline['terms'];current_cost = baseline['expected_total_eur']
        opening = supplier['opening_comparison']['expected_total_eur']
        secured = max(0.0, opening - current_cost)
        packages = {pid: p for pid, p in board['packages'].items() if p['supplier_id'] == sid}
        valid = lambda terms: agent.valid(agent.active_case, th, terms)
        for package in packages.values():
            agent.check_budget()
            package['continuation_value'] = action_value(th, package['terms'], before, supplier['status'],
                                                        th.repeats, secured, valid, current_cost)
        # Small, diverse follow-up set keeps bounded work and exposes the search restriction.
        ranked = sorted(packages, key=lambda pid: packages[pid]['continuation_value']['expected_extra_savings_eur']['mean'],
                        reverse=True)
        shortlist, structures = [], set()
        for pid in ranked:
            structure = tuple((k, str(v)) for k, v in sorted(packages[pid]['terms'].items()) if k != 'unit_price')
            if structure in structures:
                continue
            shortlist.append(pid);structures.add(structure)
            if len(shortlist) == 4:
                break
        for pid in shortlist:
            value = packages[pid]['continuation_value']
            followups = []
            # At most two counter scenarios, each from a different historical session.
            used = set()
            for scenario in sorted(value['_scenarios'], key=lambda s: s['weight'], reverse=True):
                if scenario['session_id'] in used:
                    continue
                used.add(scenario['session_id'])
                after = scenario['terms'];gain = scenario['gain']['mean']
                candidates = []
                for next_pid in shortlist:
                    next_terms = packages[next_pid]['terms']
                    if next_terms == after or next_pid == pid:
                        continue
                    estimate = action_value(th, next_terms, after, 'open', 0, max(0, secured + gain),
                                            valid, current_cost - gain)
                    candidates.append({'package_id': next_pid, 'extra_savings_eur': estimate['expected_extra_savings_eur'],
                                       'evidence': estimate['evidence']})
                best = max(candidates, key=lambda c: c['extra_savings_eur']['mean'], default=None)
                followups.append({'counter_terms': after, 'close_extra_savings_eur': scenario['gain'],
                                  'optional_followup': best,
                                  'rule': 'Reassess actual status and costs after receiving reply; close remains available. '
                                          'Hypothetical open status and further agreement are not guaranteed.'})
                if len(used) == 2:
                    break
            value['conditional_followups'] = followups
        for package in packages.values():
            value = package['continuation_value']
            value.pop('_scenarios', None);value.pop('_current_cost', None)
        supplier['fresh_closing_comparison'] = {
            'accept_now_secured_savings_eur': secured,
            'strongest_estimated_continuation_id': ranked[0] if ranked else '',
            'lookahead_package_ids': shortlist,
            'search_limit': 'All packages valued for one reply; four term structures have up to two counter scenarios '
                            'with one optional follow-up. Not exhaustive or a solved optimum.',
            'rule': 'Reconsider accepting versus continuing now. Prior stop conditions and price closeness are '
                    'hypotheses, not obligations. Astra decides and records why.'}
        supplier['learning_evidence'] = th.beliefs.learning_evidence()
